class Debt extends DataClass implements Insertable<Debt> {
  final String id;
  final DebtType type;
  final String counterpartyName;

  /// Pokok utang/piutang, selalu positif.
  final int amount;

  /// Total sudah dibayar/diterima berjalan — naik lewat
  /// [AppDatabase.recordDebtPayment], TIDAK ada kolom "lunas" terpisah
  /// (status diturunkan dari `paidAmount >= amount`, lihat [DebtView],
  /// menghindari dua sumber kebenaran yang bisa tidak sinkron).
  final int paidAmount;
  final String? note;
  final DateTime? dueDate;

  /// Dompet default saat "Catat pembayaran" — opsional, boleh dipilih ulang
  /// saat itu juga. Tanpa foreign key: dompet boleh dihapus/diarsipkan tanpa
  /// menyentuh baris ini (pola sama kolom nullable lain di app ini).
  final String? accountId;
  final DateTime createdAt;
  final DateTime updatedAt;
  const Debt({
    required this.id,
    required this.type,
    required this.counterpartyName,
    required this.amount,
    required this.paidAmount,
    this.note,
    this.dueDate,
    this.accountId,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    {
      map['type'] = Variable<int>($DebtsTable.$convertertype.toSql(type));
    }
    map['counterparty_name'] = Variable<String>(counterpartyName);
    map['amount'] = Variable<int>(amount);
    map['paid_amount'] = Variable<int>(paidAmount);
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    if (!nullToAbsent || dueDate != null) {
      map['due_date'] = Variable<DateTime>(dueDate);
    }
    if (!nullToAbsent || accountId != null) {
      map['account_id'] = Variable<String>(accountId);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  DebtsCompanion toCompanion(bool nullToAbsent) {
    return DebtsCompanion(
      id: Value(id),
      type: Value(type),
      counterpartyName: Value(counterpartyName),
      amount: Value(amount),
      paidAmount: Value(paidAmount),
      note: note == null && nullToAbsent ? const Value.absent() : Value(note),
      dueDate: dueDate == null && nullToAbsent
          ? const Value.absent()
          : Value(dueDate),
      accountId: accountId == null && nullToAbsent
          ? const Value.absent()
          : Value(accountId),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
    );
  }

  factory Debt.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Debt(
      id: serializer.fromJson<String>(json['id']),
      type: $DebtsTable.$convertertype.fromJson(
        serializer.fromJson<int>(json['type']),
      ),
      counterpartyName: serializer.fromJson<String>(json['counterpartyName']),
      amount: serializer.fromJson<int>(json['amount']),
      paidAmount: serializer.fromJson<int>(json['paidAmount']),
      note: serializer.fromJson<String?>(json['note']),
      dueDate: serializer.fromJson<DateTime?>(json['dueDate']),
      accountId: serializer.fromJson<String?>(json['accountId']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'type': serializer.toJson<int>($DebtsTable.$convertertype.toJson(type)),
      'counterpartyName': serializer.toJson<String>(counterpartyName),
      'amount': serializer.toJson<int>(amount),
      'paidAmount': serializer.toJson<int>(paidAmount),
      'note': serializer.toJson<String?>(note),
      'dueDate': serializer.toJson<DateTime?>(dueDate),
      'accountId': serializer.toJson<String?>(accountId),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
    };
  }

  Debt copyWith({
    String? id,
    DebtType? type,
    String? counterpartyName,
    int? amount,
    int? paidAmount,
    Value<String?> note = const Value.absent(),
    Value<DateTime?> dueDate = const Value.absent(),
    Value<String?> accountId = const Value.absent(),
    DateTime? createdAt,
    DateTime? updatedAt,
  }) => Debt(
    id: id ?? this.id,
    type: type ?? this.type,
    counterpartyName: counterpartyName ?? this.counterpartyName,
    amount: amount ?? this.amount,
    paidAmount: paidAmount ?? this.paidAmount,
    note: note.present ? note.value : this.note,
    dueDate: dueDate.present ? dueDate.value : this.dueDate,
    accountId: accountId.present ? accountId.value : this.accountId,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
  );
  Debt copyWithCompanion(DebtsCompanion data) {
    return Debt(
      id: data.id.present ? data.id.value : this.id,
      type: data.type.present ? data.type.value : this.type,
      counterpartyName: data.counterpartyName.present
          ? data.counterpartyName.value
          : this.counterpartyName,
      amount: data.amount.present ? data.amount.value : this.amount,
      paidAmount: data.paidAmount.present
          ? data.paidAmount.value
          : this.paidAmount,
      note: data.note.present ? data.note.value : this.note,
      dueDate: data.dueDate.present ? data.dueDate.value : this.dueDate,
      accountId: data.accountId.present ? data.accountId.value : this.accountId,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Debt(')
          ..write('id: $id, ')
          ..write('type: $type, ')
          ..write('counterpartyName: $counterpartyName, ')
          ..write('amount: $amount, ')
          ..write('paidAmount: $paidAmount, ')
          ..write('note: $note, ')
          ..write('dueDate: $dueDate, ')
          ..write('accountId: $accountId, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    type,
    counterpartyName,
    amount,
    paidAmount,
    note,
    dueDate,
    accountId,
    createdAt,
    updatedAt,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Debt &&
          other.id == this.id &&
          other.type == this.type &&
          other.counterpartyName == this.counterpartyName &&
          other.amount == this.amount &&
          other.paidAmount == this.paidAmount &&
          other.note == this.note &&
          other.dueDate == this.dueDate &&
          other.accountId == this.accountId &&
          other.createdAt == this.createdAt &&
          other.updatedAt == this.updatedAt);
